svg.script:
(function () {
  var root = document.documentElement;
  var edges = Array.prototype.slice.call(document.querySelectorAll('.edge'));
  var nodes = Array.prototype.slice.call(document.querySelectorAll('.node'));
  var current = null;
  function clear() {
    current = null; root.classList.remove('focus');
    edges.concat(nodes).forEach(function (el) { el.classList.remove('hi'); });
  }
  function focus(id) {
    if (current === id) { clear(); return; }
    clear(); current = id; root.classList.add('focus');
    var linked = {}; linked[id] = true;
    edges.forEach(function (e) {
      var ids = (e.getAttribute('data-n') || '').split(' ');
      if (ids.indexOf(id) !== -1) { e.classList.add('hi'); ids.forEach(function (x) { linked[x] = true; }); }
    });
    nodes.forEach(function (n) { if (linked[n.getAttribute('data-id')]) n.classList.add('hi'); });
  }
  nodes.forEach(function (n) {
    n.addEventListener('click', function (ev) { ev.stopPropagation(); focus(n.getAttribute('data-id')); });
    n.addEventListener('keydown', function (ev) {
      if (ev.key === 'Enter' || ev.key === ' ') { ev.preventDefault(); focus(n.getAttribute('data-id')); }
      if (ev.key === 'Escape') clear();
    });
  });
  root.addEventListener('click', clear);
})();
